        sizeRow(p,"Kalem kalınlığı",draft.pen,"pen",v->{draft.pen=v;if(drawingPreview!=null)drawingPreview.invalidate();});sizeRow(p,"Fosforlu kalem kalınlığı",draft.marker,v->draft.marker=v);sizeRow(p,"Hazır şekillerin çizgi kalınlığı",draft.shape,"shape",v->draft.shape=v);
