    interface FloatChange{void set(float v);}interface BoolChange{void set(boolean v);}interface ColorChange{void set(int v);}
    void range(LinearLayout p,String label,int min,int max,float value,String unit,FloatChange change){space(p,8);TextView title=text(label+" · "+Math.round(value)+unit,15,true);p.addView(title);SeekBar s=new SeekBar(this);s.setMax(max-min);s.setKeyProgressIncrement(1);s.setProgress(Math.max(0,Math.min(max-min,Math.round(value)-min)));s.setContentDescription(label);s.setProgressTintList(ColorStateList.valueOf(draft.ui()));s.setThumbTintList(ColorStateList.valueOf(draft.ui()));s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean user){title.setText(label+" · "+(v+min)+unit);change.set(v+min);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});p.addView(s,new LinearLayout.LayoutParams(-1,dp(48)));}
