    void color(LinearLayout p,String label,int value,ColorChange change){
        space(p,16);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView title=text(label,15,true);row.addView(title,new LinearLayout.LayoutParams(0,-2,1));ToolIcon selected=new ToolIcon(this,"color",label+" değiştir",draft);selected.swatch=value;row.addView(selected,new LinearLayout.LayoutParams(dp(52),dp(52)));p.addView(row);
        LinearLayout picker=new LinearLayout(this);picker.setOrientation(LinearLayout.VERTICAL);picker.setVisibility(View.GONE);p.addView(picker);selected.setOnClickListener(v->picker.setVisibility(picker.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));
        EditText input=new EditText(this);GridLayout palette=new GridLayout(this);palette.setColumnCount(5);for(int color:new int[]{0xff00d9f5,0xff3b82f6,0xffa78bfa,0xffef4444,0xfff59e0b,0xfffacc15,0xff22c55e,0xffff00ff,0xffffffff,0xff000000}){ToolIcon swatch=new ToolIcon(this,"color",Prefs.hex(color),draft);swatch.swatch=color;swatch.setOnClickListener(v->{change.set(color);selected.swatch=color;selected.invalidate();input.setText(Prefs.hex(color));picker.setVisibility(View.GONE);});GridLayout.LayoutParams lp=new GridLayout.LayoutParams();lp.width=dp(48);lp.height=dp(48);lp.setMargins(0,dp(6),dp(6),0);palette.addView(swatch,lp);}picker.addView(palette);
        LinearLayout custom=advanced(picker,"Özel renk kodu");input.setSingleLine();input.setText(Prefs.hex(value));input.setTextSize(15);input.setTextColor(draft.text());input.setContentDescription(label+" renk kodu");input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);custom.addView(input,new LinearLayout.LayoutParams(-1,dp(52)));input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){try{if(!s.toString().matches("#[0-9a-fA-F]{6}([0-9a-fA-F]{2})?"))throw new IllegalArgumentException();int c=Color.parseColor(s.toString());change.set(c);selected.swatch=c;selected.invalidate();input.setError(null);invalid.remove(input);}catch(Exception e){input.setError("#RRGGBB veya #AARRGGBB");invalid.add(input);}}public void afterTextChanged(Editable e){}});
    }
    TextView text(String value,int size,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(draft.text());t.setLineSpacing(dp(3),1);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    void heading(LinearLayout p,String title){space(p,16);p.addView(text(title,20,true));space(p,8);}
    void desc(LinearLayout p,String value){TextView t=text(value,15,false);t.setTextColor(draft.muted());p.addView(t);space(p,14);}
    void space(LinearLayout p,int n){View v=new View(this);p.addView(v,new LinearLayout.LayoutParams(1,dp(n)));}
    Button button(String value,Runnable action){return UiKit.button(this,draft,value,false,action);}
    void status(String msg,boolean error){feedback.setVisibility(msg.isEmpty()?View.GONE:View.VISIBLE);feedback.setTextColor(error?(draft.light?0xffa51b26:0xffffa5ad):draft.muted());feedback.setText(msg);}
    void export(){try{operation="export-profile";if(!invalid.isEmpty())throw new IOException("Renk kodlarını düzeltin.");pendingBytes=draft.json().toString(2).getBytes("UTF-8");picking=true;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"GVNpen-profil.json"),20);}catch(Exception e){picking=false;status("Dışa aktarılamadı: "+e.getMessage(),true);}}
    void importFile(){operation="import-profile";picking=true;try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),21);}catch(Exception e){picking=false;status("Dosya seçici açılamadı: "+e.getMessage(),true);}}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);picking=false;if(result!=RESULT_OK||data==null||data.getData()==null){pendingBytes=null;return;}Uri uri=data.getData();
        if(req==20){byte[] bytes=pendingBytes;pendingBytes=null;if(bytes==null){status("Ekran yeniden oluşturuldu; dışa aktarma işlemini tekrar başlatın.",true);return;}files.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Dosya açılamadı.");out.write(bytes);runOnUiThread(()->status("Dosya kaydedildi.",false));}catch(Exception e){runOnUiThread(()->status("Kaydedilemedi: "+e.getMessage(),true));}});}
        if(req==21)files.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Dosya açılamadı.");ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(b.size()+n>1024*1024)throw new IOException("Dosya çok büyük.");b.write(buf,0,n);}JSONObject parsed=new JSONObject(b.toString("UTF-8"));if(!parsed.has("PenSize")&&!parsed.optString("format").equals("GVNpen-profile-1"))throw new IOException("GVNpen profili değil.");Prefs loaded=Prefs.from(parsed);runOnUiThread(()->{draft=loaded;show();status("Profil taslağa alındı. Kaydet ile etkinleşir.",false);});}catch(Exception e){runOnUiThread(()->status("Açılamadı: "+e.getMessage(),true));}});
    }
